let mode='front';const frame=document.querySelector('iframe');const descriptions={png:'The new transparent PNG over the same moving halo. Baked highlights, no live refraction.',front:'The v4 model, facing forward. The halo moves through the glass while the silhouette stays still.',tilt:'Move the pointer across the scene. A small tilt reveals the continuous folded ribbon. No automatic spinning.'};function update(){const params=new URLSearchParams({mode,text:document.querySelector('#text').checked?'1':'0',pause:document.querySelector('#pause').checked?'1':'0',frost:document.querySelector('#frost').value});frame.src='../../brand-glass/scene.html?'+params;document.querySelector('#explanation').textContent=descriptions[mode];document.querySelector('#frost').disabled=mode==='png';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)))}document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;update()});document.querySelectorAll('input').forEach(input=>input.addEventListener('change',update));document.querySelector('#frost').oninput=e=>document.querySelector('#frost-value').value=e.target.value;document.querySelector('#reset').onclick=()=>{document.querySelector('#frost').value='0.1';document.querySelector('#frost-value').value='0.1';update()};